function eggContent(s){
  const pal={shirt:'#7a3a5a',skin:'#e8b98a',hair:'#2a1d14',long:true};
  const t=s.egg===2?'Titolo in arrivo, parte seconda':'Titolo in arrivo';
  const L=[[t,['Relatore/i: '+s.sp,'Sull’app c’era scritto «Titolo in arrivo»'],'Slide inventate per il gioco. Su entrambe le fonti consultate, per questa sessione, c’era scritto soltanto «Titolo in arrivo»: eccolo, il titolo è arrivato.','Il titolo arriva sempre, anche se dopo.'],
   ['Perché un titolo conta',['Promette un risultato','Si scrive per ultimo'],'Un buon titolo dice cosa c’è dentro. Un cattivo titolo dice solo «in arrivo».','Scrivi venti titoli e scegli il più chiaro.'],
   {q:'Come intitoli un intervento che non ha ancora un titolo?',c:[{t:'«Titolo in arrivo», e speriamo che nessuno se ne accorga.',r:'Divertente, ma l’hanno già visto in due.',good:false},{t:'Scrivo venti titoli e scelgo il più chiaro.',r:'Esatto: titolo chiaro, promessa concreta.',good:true},{t:'Lascio la slide bianca.',r:'Il pubblico resta senza una promessa.',good:false}]},
   ['Easter egg',['Due fonti, un titolo mancante','Il pubblico se n’è accorto'],'Se stai leggendo questa slide, hai trovato il «Titolo in arrivo». Complimenti!','Chi cerca il titolo, lo trova.']];
  return {title:t,speaker:s.sp,role:s.role,pal,slides:s.egg===2?L.slice(0,3).concat([L[3]]):L};
}
function makeContent(s){
  if(s.c)return s.c;
  if(s.egg)return s.c=eggContent(s);
  const keys=(s.tags&&s.tags.length?s.tags:['Business']).map(t=>TOPIC_TIPS[t]||'sale');
  const pool=[];keys.forEach(k=>(TIPS[k]||MORE_TIPS[k]||TIPS.sale).forEach(t=>pool.push(t)));
  const pick=(i)=>pool[(i*3+s.title.length)%pool.length];
  const sh=s.title.length>46?s.title.slice(0,44)+'…':s.title;
  const good=pick(1);
  s.c={title:s.title,speaker:s.sp,role:s.role,pal:{shirt:['#3a4a8a','#8a3a4a','#3a7a5a','#6a4a8a','#aa7a3a','#3a6a8a'][s.title.length%6],skin:['#e8b98a','#dfae80','#c98e62','#f0c8a0'][s.sp.length%4],hair:['#2a1d14','#4a3322','#1a1a20','#8a3a2a'][s.title.length%4],long:s.title.length%3===0},slides:[
   [sh,['Relatore: '+(s.sp||'—'),s.role||''],'Slide e spunti inventati per il gioco: non sono i contenuti reali della sessione. Il tema: «'+sh+'».','Tema della sessione: '+sh],
   ['Primo spunto',['Parti da una cosa concreta','Misura prima di cambiare'],'Sul tema: '+pick(0),pick(0)],
   ['Secondo spunto',['Fai un passo alla volta','Scrivilo prima di farlo'],'Sul tema: '+pick(1),pick(1)],
   {q:'Quale di queste azioni applicheresti per prima?',c:[{t:'Aspetto che lo faccia qualcun altro prima di me.',r:'Rimandare non porta risultati.',good:false},{t:good.replace(/\.$/,''),r:'Giusto: '+good,good:true},{t:'Cambio tutto in una volta, senza misurare.',r:'Troppo rischioso: meglio un passo alla volta.',good:false}]},
   ['Ultimo spunto',['Porta a casa una sola azione','Falla entro domani'],'Sul tema: '+pick(2),pick(2)]]};
  return s.c;
}
(function buildProgram(){
  const m=t=>+t.slice(0,2)*60+ +t.slice(3);let id=0;
  FRIDAY.forEach(s=>{s.d=0;s.id=id++;s.start=m(s.t);PROGRAMMA.push(s);});
  PROGRAMMA.push({d:0,id:id++,t:'13:00',start:13*60,e:13*60+30,title:'Pausa pranzo e networking',room:'Area networking',kind:'lounge',tags:[],sp:'',role:''});
  SATURDAY.forEach(s=>{s.d=1;s.id=id++;s.start=m(s.t);PROGRAMMA.push(s);});
  let ti=0;
  for(const d of [2]){WEEKEND_SLOTS.forEach(t=>{const tk=TALKS[(ti++)%TALKS.length];PROGRAMMA.push({d,id:id++,t,start:m(t),e:m(t)+60,title:tk.title,room:'Main Stage',sp:tk.speaker,role:tk.role,tags:[],kind:'talk',c:tk,invented:true});});
   PROGRAMMA.push({d,id:id++,t:'12:30',start:12*60+30,e:14*60,title:'Pausa pranzo e networking',room:'Area networking',kind:'lounge',tags:[],sp:'',role:''});}
  PROGRAMMA.sort((a,b)=>a.d-b.d||a.start-b.start);
})();
